cases.bad:
// Rich cache first — stale-but-non-null short-circuits ??
const videoId =
  getVideoIdFromPlayerResponse(playerResponse) ?? getVideoIdFromUrl();
// SPA nav: playerResponse still holds OLD videoId (non-null) → ?? picks it
// → currentVideoId === lastVideoId → detect never re-runs → no autoload

cases.good:
// Freshest source first — URL mutates on SPA nav before cache rebuilds
const videoId =
  getVideoIdFromUrl() ?? getVideoIdFromPlayerResponse(playerResponse);
// SPA nav: location.href already has new v → detect re-runs → autoload fires
// playerResponse fallback covers edge cases where URL lacks v
